package io.lmctl.lmcode;
import java.nio.file.*;import java.nio.file.attribute.BasicFileAttributes;import java.io.*;import java.util.*;import java.nio.charset.*;import java.net.URI;
final class StdFile {
 static void register(Registry r){
  r.function("file_read",List.of("string"),"string",(c,s,a)->Value.ofString(read(c,"file_read",a[0].asString())));
  r.function("file_write",List.of("string","string"),"void",(c,s,a)->{write("file_write",a[0].asString(),a[1].asString().bytes(),false);return Value.none();});
  r.function("file_append",List.of("string","string"),"void",(c,s,a)->{write("file_append",a[0].asString(),a[1].asString().bytes(),true);return Value.none();});
  r.function("file_exists",List.of("string"),"bool",(c,s,a)->Value.ofBool(exists("file_exists",a[0].asString())));
  r.function("file_lines",List.of("string"),"StrList",(c,s,a)->{byte[]b=read(c,"file_lines",a[0].asString()).bytes();ArrayList<VmString>x=new ArrayList<>();int at=0;for(int i=0;i<b.length;i++)if(b[i]=='\n'){x.add(new VmString(Arrays.copyOfRange(b,at,i)));at=i+1;}x.add(new VmString(Arrays.copyOfRange(b,at,b.length)));return StdCollections.obj(c,"StrList",x);});
 }
 static Path path(String f,VmString v){byte[]b=v.bytes();for(byte x:b)if(x==0)throw failure(f,v,"invalid argument");if(isWindows()){strictUtf8(f,b);return Path.of(new String(b,StandardCharsets.UTF_8));}return Path.of(URI.create(fileUri(b)));}
 static VmString read(Context c,String f,VmString v){try{Path p=path(f,v);rejectDevice(f,v,p);BasicFileAttributes a=Files.readAttributes(p,BasicFileAttributes.class);if(!a.isRegularFile())throw new IOException("invalid argument");long size=a.size();if(size>Integer.MAX_VALUE)throw new IOException("file is too large");c.charge(size);return new VmString(Files.readAllBytes(p));}catch(VmException e){throw e;}catch(Exception e){throw failure(f,v,e.getMessage());}}
 static boolean exists(String f,VmString v){try{Path p=path(f,v);if(isWindowsDevice(p))return false;return Files.readAttributes(p,BasicFileAttributes.class).isRegularFile();}catch(VmException e){throw e;}catch(NoSuchFileException|NotDirectoryException e){return false;}catch(InvalidPathException e){throw failure(f,v,"invalid argument");}catch(Exception e){throw failure(f,v,e.getMessage());}}
 static void write(String f,VmString v,byte[]d,boolean app){try{Path p=path(f,v);rejectDevice(f,v,p);try{if(!Files.readAttributes(p,BasicFileAttributes.class).isRegularFile())throw new IOException("invalid argument");}catch(NoSuchFileException|NotDirectoryException ignored){}if(app)Files.write(p,d,StandardOpenOption.CREATE,StandardOpenOption.APPEND);else Files.write(p,d,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);try(OutputStream o=Files.newOutputStream(p,StandardOpenOption.APPEND)){o.flush();}}catch(VmException e){throw e;}catch(Exception e){throw failure(f,v,e.getMessage());}}
 static boolean isWindows(){return System.getProperty("os.name").startsWith("Windows");}
 static String fileUri(byte[] raw){byte[] path=raw;if(raw.length==0||raw[0]!='/'){byte[] cwd=Path.of("").toAbsolutePath().toString().getBytes(StandardCharsets.UTF_8);path=new byte[cwd.length+1+raw.length];System.arraycopy(cwd,0,path,0,cwd.length);path[cwd.length]='/';System.arraycopy(raw,0,path,cwd.length+1,raw.length);}StringBuilder u=new StringBuilder("file://");for(byte x:path){int c=x&255;if(c=='/'||(c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='.'||c=='_'||c=='~')u.append((char)c);else u.append(String.format(Locale.ROOT,"%%%02X",c));}return u.toString();}
 static boolean isWindowsDevice(Path p){if(!isWindows())return false;String n=p.getFileName()==null?"":p.getFileName().toString();int dot=n.indexOf('.');String b=(dot<0?n:n.substring(0,dot)).toUpperCase(Locale.ROOT);return b.equals("CON")||b.equals("PRN")||b.equals("AUX")||b.equals("NUL")||(b.startsWith("COM")&&number(b,3))||(b.startsWith("LPT")&&number(b,3));}
 static boolean number(String s,int at){return s.length()==at+1&&s.charAt(at)>='1'&&s.charAt(at)<='9';}
 static void rejectDevice(String f,VmString v,Path p){if(isWindowsDevice(p))throw failure(f,v,"invalid argument");}
 static void strictUtf8(String f,byte[] b){try{StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(b));}catch(CharacterCodingException e){throw failure(f,new VmString(b),e.getMessage());}}
 static VmException failure(String f,VmString v,String why){return VmException.host(f+": "+display(v)+": "+(why==null||why.isEmpty()?"file operation failed":why));}
 static String display(VmString v){try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(v.bytes())).toString();}catch(CharacterCodingException e){StringBuilder s=new StringBuilder("bytes:");for(byte b:v.bytes())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}}
}
